import{_ as n,C as a,o,c as i,E as r,a2 as s}from"./chunks/framework.Cm6XCzck.js";const f=JSON.parse('{"title":"Waiting Is a Runtime State, Not an Agent Loop","description":"","frontmatter":{"schema":"publication-candidate-article/v2","title":"Waiting Is a Runtime State, Not an Agent Loop","date":"2026-08-19","column":"digital-employee","category":"academic","article_type":"technical-analysis","edition":"research-center","research_question":"What architectural conclusion is actually supported by SentinelBench about long-running monitoring agents: is reliable waiting primarily a model capability, a polling strategy, or a runtime state that should be separated from continuous reasoning and action?","summary":"SentinelBench provides primary evidence that monitoring is a distinct agent workload: condition-aware waiting can reduce cost and improve completion on long waits, but production monitoring still needs durable condition state, explicit admission and separately verified effects.","sources":"arXiv:2606.05342v2; Microsoft Research SentinelBench article; microsoft/sentinel_environments @ 0faca33cc58ea62e97a928b67cd3beec7176b408; research/reading/Q-20260804-11-sentinelbench-monitoring.md; research/analysis/Q-20260804-11-sentinelbench-monitoring.md","cover":"/assets/covers/academic-sentinelbench-waiting-runtime-v2.png"},"headers":[],"relativePath":"en/digital-employee/2026-08-19-sentinelbench-waiting-runtime.md","filePath":"en/digital-employee/2026-08-19-sentinelbench-waiting-runtime.md","lastUpdated":1787382334000}'),c={name:"en/digital-employee/2026-08-19-sentinelbench-waiting-runtime.md"};function l(d,e,h,p,u,m){const t=a("ArticleCover");return o(),i("div",null,[r(t,{image:"/assets/covers/academic-sentinelbench-waiting-runtime-v2.png",kicker:"Digital Employee · Academic Observation 004",title:"Waiting Is a Runtime State",summary:"A monitoring agent should preserve what it is waiting for independently of the model turn that happens to be awake.",version:"DA004",status:"Academic Runtime V5 · 2026-08-19",languageHref:"/zh/digital-employee/2026-08-19-sentinelbench-waiting-runtime",languageLabel:"简体中文"}),e[0]||(e[0]=s('<h1 id="waiting-is-a-runtime-state-not-an-agent-loop" tabindex="-1">Waiting Is a Runtime State, Not an Agent Loop <a class="header-anchor" href="#waiting-is-a-runtime-state-not-an-agent-loop" aria-label="Permalink to &quot;Waiting Is a Runtime State, Not an Agent Loop&quot;">​</a></h1><p>Some agent jobs fail because the agent does too little. Monitoring jobs can fail because the agent does too much.</p><p>If the instruction is “tell me when a ticket appears,” “alert me when three more unread messages arrive,” or “act when a price crosses this threshold,” refreshing a page more aggressively does not make the external event happen sooner. A model that keeps reasoning, clicking and polling may spend more tokens, create more failure opportunities, and still give up before the condition becomes true.</p><p>That inversion is what makes Microsoft&#39;s 2026 <strong>SentinelBench</strong> useful. The benchmark is not primarily about making an agent think for longer. It makes <strong>waiting itself</strong> measurable. Its 100 tasks run across ten synthetic web environments whose state changes independently of the agent, and its evaluation tracks whether the task was completed, how quickly the agent reacted after the target event, and how much inference/tool work the run consumed. The paper and code are publicly available through <a href="https://arxiv.org/abs/2606.05342" target="_blank" rel="noreferrer">arXiv:2606.05342v2</a> and the <a href="https://github.com/microsoft/sentinel_environments" target="_blank" rel="noreferrer">Microsoft sentinel_environments repository</a>.</p><p>The evidence supports a bounded engineering judgment: <strong>monitoring should be represented as a runtime state, not improvised as a sequence of free-form agent turns.</strong> SentinelBench does not prove a production monitoring architecture, but it makes the missing runtime boundaries unusually visible.</p><h2 id="monitoring-is-not-merely-a-long-task" tabindex="-1">Monitoring is not merely a long task <a class="header-anchor" href="#monitoring-is-not-merely-a-long-task" aria-label="Permalink to &quot;Monitoring is not merely a long task&quot;">​</a></h2><p>A conventional long-horizon agent benchmark usually assumes that progress comes from the agent doing something: open the application, inspect state, choose a tool, change the environment, repeat.</p><p>SentinelBench deliberately breaks that assumption. Once a scenario starts, scheduled events update the backing database and web interface on their own. The agent may need to notice a new email, a new job posting, a stock-price change, a calendar invitation, or another event that was not caused by its previous action. The benchmark therefore asks not only <strong>what should the agent do next?</strong>, but also <strong>should it be doing anything yet?</strong></p><p>The task set makes this distinction concrete. According to the <a href="https://arxiv.org/html/2606.05342v2" target="_blank" rel="noreferrer">primary paper</a>, SentinelBench contains 20 no-operation tasks; the other 80 are divided between active and passive tasks, and between absolute and relative conditions. These are not cosmetic labels.</p><p>A passive task can be satisfied mainly by detecting that a condition has become true. An active task may require opening conversations, inspecting hidden details, or changing application state after detection. An absolute condition can often be judged from the current state. A relative condition — “three more unread alerts than there are now” — requires preserving a baseline across time.</p><p>The no-operation cases are especially important. In those tasks the target condition never becomes true. The correct result is to keep monitoring until the window ends without inventing a success event. That gives the benchmark a failure mode many ordinary agent evaluations miss: <strong>premature completion is itself an error.</strong></p><h2 id="the-benchmark-separates-activity-from-outcome" tabindex="-1">The benchmark separates activity from outcome <a class="header-anchor" href="#the-benchmark-separates-activity-from-outcome" aria-label="Permalink to &quot;The benchmark separates activity from outcome&quot;">​</a></h2><p>SentinelBench&#39;s released harness does not simply ask whether the agent&#39;s final message sounds plausible. The scenario includes a database query used to evaluate the resulting state. The server also records when the agent signals completion relative to the target condition. The <a href="https://github.com/microsoft/sentinel_environments" target="_blank" rel="noreferrer">repository README</a> describes ordinary success as requiring both a truthy scenario evaluation and completion at or after the condition time; no-op scenarios require the agent never to signal completion.</p><p>This is a useful methodological choice because detection and effect are different things.</p><p>An agent can correctly notice that a matching job appeared but fail to apply. It can detect an email but alert the user too early. It can confidently say that nothing happened when the monitoring window is still open. A long action trace may look diligent while the requested business state is wrong.</p><p>That suggests a general evaluation rule for monitoring systems: <strong>worker activity is evidence about process, not proof of completion.</strong> The requested external condition and the requested downstream effect need their own evidence.</p><h2 id="wait-for-changes-where-the-waiting-work-lives" tabindex="-1"><code>wait_for</code> changes where the waiting work lives <a class="header-anchor" href="#wait-for-changes-where-the-waiting-work-lives" aria-label="Permalink to &quot;`wait_for` changes where the waiting work lives&quot;">​</a></h2><p>The paper compares two browser-agent configurations. One gives the agent a conventional <code>sleep(time)</code> tool. The other gives it a purpose-built <code>wait_for(condition, timeout)</code> tool.</p><p>The important difference is not that one function name is better than another. It is where the monitoring state lives.</p><p>With <code>sleep</code>, the model decides how long to pause, wakes up, observes the page, reasons again, and may repeat the cycle. The condition itself remains largely embedded in the agent trajectory.</p><p>With the evaluated <code>wait_for</code>, the condition and timeout become explicit tool arguments. The prototype captures a textual baseline of the page, checks for new page-state differences, suppresses diff blocks it has already evaluated, rate-limits LLM checks, periodically reloads the page, and performs a final forced check when the timeout expires. Appendix D of the paper specifies adaptive intervals rather than calling the model on every one-second observation loop.</p><p>That implementation is still polling. It is not a webhook, a durable event stream, or a production notification service. But architecturally it separates three things that a free-running agent loop tends to collapse:</p><ul><li><strong>condition state</strong> — what the worker is waiting for;</li><li><strong>observation policy</strong> — how the environment is sampled;</li><li><strong>reasoning invocation</strong> — when a new observation is important enough to ask the model.</li></ul><p>Once those are separate, the observation mechanism can change without rewriting the user intent. A browser diff, database watch, provider webhook or event stream could all, in principle, feed the same higher-level condition contract.</p><h2 id="the-baseline-is-a-trade-off-not-a-theorem" tabindex="-1">The baseline is a trade-off, not a theorem <a class="header-anchor" href="#the-baseline-is-a-trade-off-not-a-theorem" aria-label="Permalink to &quot;The baseline is a trade-off, not a theorem&quot;">​</a></h2><p>The authors&#39; reported results are useful precisely because they do <strong>not</strong> reduce to “condition-aware waiting wins every metric.” These are source-reported research results from the authors&#39; own controlled benchmark; this Academic run did not identify an independent reproduction of the complete baseline.</p><p>For the default-duration GPT-5.4 condition, the paper reports overall success of <strong>0.75 with <code>wait_for</code> versus 0.68 with <code>sleep</code></strong>. Median per-task API cost is reported as <strong>$0.23 versus $1.17</strong>, and the median tool-call count as <strong>6 versus 19.5</strong>.</p><p>The longer experiment sharpens the cost difference. With <code>speed_factor = 0.25</code>, tasks can extend to about forty minutes. The authors report <strong>69 successful tasks with <code>wait_for</code> versus 56 with <code>sleep</code></strong>, while median API cost is <strong>$0.48 versus $4.65</strong> — a reported 9.7× difference.</p><p>But reaction time moves the other way in that GPT-5.4 comparison: the reported median is <strong>54.8 seconds with <code>wait_for</code> versus 38.9 seconds with <code>sleep</code></strong> in the stretched-duration setting. The default-duration GPT-5.4 result shows the same direction: <code>wait_for</code> is somewhat slower on median reaction time even while it costs less and completes more tasks.</p><p>That is not a weakness in the benchmark. It is the point. Monitoring quality is not one scalar. It includes at least:</p><ul><li>completion reliability;</li><li>premature-success and missed-event risk;</li><li>reaction latency;</li><li>inference and tool cost;</li><li>correctness of any consequential side effect.</li></ul><p>A five-second polling loop may react quickly and be wasteful. A heavily backed-off monitor may be cheap and miss a short-lived event. The runtime therefore needs an explicit service objective for the job rather than one universal polling cadence.</p><h2 id="a-production-monitor-needs-four-boundaries" tabindex="-1">A production monitor needs four boundaries <a class="header-anchor" href="#a-production-monitor-needs-four-boundaries" aria-label="Permalink to &quot;A production monitor needs four boundaries&quot;">​</a></h2><p>SentinelBench does not publish the following contract. It is the Research Center&#39;s synthesis from the benchmark design, the released implementation and the limitations the authors state.</p><table tabindex="0"><thead><tr><th>Boundary</th><th>Runtime question</th><th>Evidence needed</th></tr></thead><tbody><tr><td><strong>Condition state</strong></td><td>What exactly are we waiting for?</td><td>Stable monitor identity, predicate, baseline/reference state, scope and expiry</td></tr><tr><td><strong>Observation policy</strong></td><td>How will we notice change?</td><td>Source, mechanism, cadence/backoff, latency target, cost/rate-limit budget</td></tr><tr><td><strong>Condition admission</strong></td><td>Is the condition sufficiently satisfied to proceed?</td><td>Observed state, predicate decision, uncertainty and authority to advance</td></tr><tr><td><strong>Effect evidence</strong></td><td>Did the requested notification/action actually happen?</td><td>External acceptance, action/notification identity, deduplication and terminal result</td></tr></tbody></table><p>This decomposition matters because the four layers fail differently.</p><p>A process can restart and lose the baseline while the observation mechanism remains healthy. A page watcher can detect a change that does not actually satisfy the user&#39;s condition. A condition can be correctly admitted while the downstream notification never reaches its sink. The requested action can succeed twice because the monitor does not remember that it already acted on the same occurrence.</p><p>Calling all of these “the agent is monitoring” hides the failure location. Treating them as separate runtime state makes recovery and audit possible.</p><h3 id="relative-conditions-make-durable-state-unavoidable" tabindex="-1">Relative conditions make durable state unavoidable <a class="header-anchor" href="#relative-conditions-make-durable-state-unavoidable" aria-label="Permalink to &quot;Relative conditions make durable state unavoidable&quot;">​</a></h3><p>SentinelBench&#39;s relative tasks expose this cleanly. “Alert me at 100 likes” can be evaluated from one snapshot. “Alert me after 100 more likes” needs a reference value from the start of the monitoring episode.</p><p>If that baseline exists only in transient model context, a crash or context reset changes the meaning of the task. A production monitor therefore needs a durable condition identity and reference state independent of whichever model turn happens to be awake.</p><h3 id="no-op-needs-a-governed-terminal-outcome" tabindex="-1">No-op needs a governed terminal outcome <a class="header-anchor" href="#no-op-needs-a-governed-terminal-outcome" aria-label="Permalink to &quot;No-op needs a governed terminal outcome&quot;">​</a></h3><p>A no-op task is not a task where “nothing happened and the worker forgot to work.” It is a task where the condition did not occur within the governed window, and no consequential action was authorized.</p><p>That distinction is operationally important. A runtime should be able to close a monitor as <code>ConditionNotMet</code>, <code>Expired</code>, or another explicit outcome without forcing the agent to fabricate an event merely to produce a conventional success message.</p><h3 id="detection-is-not-delivery" tabindex="-1">Detection is not delivery <a class="header-anchor" href="#detection-is-not-delivery" aria-label="Permalink to &quot;Detection is not delivery&quot;">​</a></h3><p>The benchmark&#39;s database-state evaluation also points toward a second separation: <strong>condition detection is not external effect evidence</strong>.</p><p>A monitor that notices a qualifying event has not yet proved that a message was delivered, an order was accepted, a ticket was created, or a business record reached the correct system. For consequential monitoring, the effect needs its own durable identity and acknowledgement/evidence surface.</p><h2 id="where-the-evidence-stops" tabindex="-1">Where the evidence stops <a class="header-anchor" href="#where-the-evidence-stops" aria-label="Permalink to &quot;Where the evidence stops&quot;">​</a></h2><p>The paper is careful about several boundaries.</p><p>Event timing is artificial. Target times are generated inside a controlled simulation rather than sampled from real service distributions. The ten environments are lightweight synthetic facsimiles, not production websites, and the authors explicitly note that untested trajectories may expose errors or missing behavior.</p><p>Most success criteria are objective. Subjective conditions such as “alert me when an urgent bug appears” remain underexplored. Most target conditions are persistent once true; ephemeral conditions — where an opportunity exists only briefly — are a harder future case identified by the paper.</p><p>The evaluated <code>wait_for</code> tool is also a prototype over page text and periodic reloads. SentinelBench does not establish crash-safe monitor restoration, exactly-once notification or action, credential renewal, cross-monitor rate-limit arbitration, repeated-occurrence identity, or transactional compensation for side effects.</p><p>And publication is not validation. The paper, Microsoft Research article and open-source repository establish provenance, inspectability and a reproducible benchmark package. They do not by themselves establish that the reported baseline generalizes to production monitoring agents.</p><h2 id="what-should-be-tested-next" tabindex="-1">What should be tested next? <a class="header-anchor" href="#what-should-be-tested-next" aria-label="Permalink to &quot;What should be tested next?&quot;">​</a></h2><p>The next useful experiment is not simply to run a longer sleep.</p><p>A production-oriented evaluation should interrupt a monitor mid-wait, restart the worker, and ask whether the exact same condition identity and baseline can be reconstructed without duplicate action. It should include ephemeral conditions whose value disappears if reaction is too slow. It should include subjective admission where a model decision needs auditable evidence rather than a numeric threshold. It should run many monitors against shared credentials and rate limits. And it should compare browser polling with provider-native events while holding the condition and effect contracts constant.</p><p>Those tests would answer a question SentinelBench intentionally leaves open: can the measurable advantages of condition-aware waiting survive the failure modes of a real long-running runtime?</p><p>The current evidence already supports a more modest architectural shift. <strong>An agent should not have to keep thinking merely to keep waiting.</strong> The monitor&#39;s condition, observation policy and completion evidence should persist as runtime state; model reasoning should be invoked when the runtime has new evidence or a governed decision to make.</p><p>That is a narrower claim than “event-driven agents solve monitoring.” It is also a much more useful one to engineer against.</p><h2 id="evidence-and-sources" tabindex="-1">Evidence and sources <a class="header-anchor" href="#evidence-and-sources" aria-label="Permalink to &quot;Evidence and sources&quot;">​</a></h2><ol><li>Matheus Kunzler Maldaner et al., <strong>SentinelBench: A Benchmark for Long-Running Monitoring Agents</strong>, arXiv:2606.05342v2, June 5, 2026 — <a href="https://arxiv.org/abs/2606.05342" target="_blank" rel="noreferrer">https://arxiv.org/abs/2606.05342</a></li><li>Full paper HTML — <a href="https://arxiv.org/html/2606.05342v2" target="_blank" rel="noreferrer">https://arxiv.org/html/2606.05342v2</a></li><li>Microsoft Research, <strong>SentinelBench, a Benchmark for Long-Running Monitoring Agents</strong>, June 8, 2026 — <a href="https://www.microsoft.com/en-us/research/articles/sentinelbench-a-benchmark-for-long-running-monitoring-agents/" target="_blank" rel="noreferrer">https://www.microsoft.com/en-us/research/articles/sentinelbench-a-benchmark-for-long-running-monitoring-agents/</a></li><li>Microsoft, <strong>sentinel_environments</strong>, inspected at commit <code>0faca33cc58ea62e97a928b67cd3beec7176b408</code> — <a href="https://github.com/microsoft/sentinel_environments" target="_blank" rel="noreferrer">https://github.com/microsoft/sentinel_environments</a></li><li>Governed Deep Reading — <code>research/reading/Q-20260804-11-sentinelbench-monitoring.md</code></li><li>Governed Research Analysis — <code>research/analysis/Q-20260804-11-sentinelbench-monitoring.md</code></li></ol><p><strong>Evidence boundary:</strong> items 1–4 are the authors&#39; primary paper, official article and first-party released implementation. They are public primary sources, not independent reproduction. The architecture proposed in this article is explicitly a Research Center interpretation derived from those sources.</p>',62))])}const b=n(c,[["render",l]]);export{f as __pageData,b as default};
